  SchoolConfig_3_SchoolBattleTips_1 = {
    Text = "·เคลื่อนผ่านมิติ: หลังจากเล่นการ์ดคำสั่งครั้งแรกในแต่ละเทิร์น จะเกิดผลนี้ขึ้น โดยนำสำเนาต้นฉบับชั่วคราวของการ์ดนั้นใส่ไว้ในมิติพิเศษ ไม่สามารถเปิดใช้ผลนี้ในเทิร์นอัลตร้า\n·เทิร์นอัลตร้า: เมื่อเข้าสู่เทิร์นอัลตร้า จะนำการ์ดทั้งหมดในมิติพิเศษใส่ไว้ในมือแทนการจั่วไพ่ ความเสียหาย, โล่, การฟื้นฟู HP, พลังงานกุญแจเงิน, อาลีมัส, การเปลี่ยนแปลงพละกำลัง, พิษ, การโต้กลับ, เลือดออก ที่เกิดขึ้นในเทิร์นอัลตร้าจะลดลง 25％\n·ทำลายล้าง: 1 ครั้งต่อเทิร์น สามารถลบการ์ดที่อยู่ซ้ายสุดในมิติพิเศษออก และนำการ์ด「แรงบัลดาลใจ」1 ใบใส่ไว้ในมือ\n·มิติพิเศษเชี่ยวชาญ: ทุก 1 คะแนนความชำนาญดินแดนของทีม จะมีโอกาส 0.125％ (<BlueQuality:[Arg1]%>) ในการรับ「แรงบัลดาลใจ」1 ใบเมื่อเริ่มเทิร์น หากโอกาสเกิน 100％ สามารถรับได้หลายใบ\n·บริสุทธิ์สูงสุดมิติพิเศษ: หากทีมประกอบด้วยตัวเร่งการตื่นในมิติพิเศษเท่านั้น ผลของมิติพิเศษเชี่ยวชาญจะเพิ่มเป็นสองเท่า และจะไม่ได้รับผลการลดความสามารถในเทิร์นอัลตร้าอีกต่อไป"
  },
  SchoolConfig_3_SchoolBattleTips_2 = {
    Text = "·เคลื่อนผ่านมิติ: หลังจากเล่นการ์ดคำสั่งครั้งแรกในแต่ละเทิร์น จะเกิดผลนี้ขึ้น โดยนำสำเนาต้นฉบับชั่วคราวของการ์ดนั้นใส่ไว้ในมิติพิเศษ และมอบ <BlueQuality:[Arg2]> สะสม「สัญญาณจุดวิกฤติ」ให้กับการ์ดนั้นและสำเนาชั่วคราว ไม่สามารถเปิดใช้ผลนี้ในเทิร์นอัลตร้า\n·สัญญาณจุดวิกฤติ: ทุก 1 สะสม จะเพิ่มความเสียหาย, พละกำลังคงที่และความเสียหายจากหนวดสัมผัส, พิษคงที่, ผลสุดท้ายของการโต้กลับคงที่ 2％; เพิ่มผลสุดท้ายของโล่คงที่, การฟื้นฟู HP คงที่, STR▼ 1％ และจะถูกลบออกหลังจากเล่น การ์ดที่มีสัญญาณจุดวิกฤติไม่สามารถเปิดใช้「เคลื่อนผ่านมิติ」ได้\n·มิติพิเศษ: เมื่อถึงขีดจำกัด เมื่อสิ้นสุดเทิร์นจะเปิดใช้มิติพิเศษแทน ไม่รับเทิร์นพิเศษเพิ่มเติม ทิ้งไพ่บนมือที่ไม่ได้เก็บรักษาและเปิดใช้ผลสุญญตา, นำการ์ดทั้งหมดในมิติพิเศษใส่ไว้ในมือ และตั้งค่าอริธเมทิกาปัจจุบันเป็น 5 คะแนน หลังจากเปิดใช้มิติพิเศษ เทิร์นนี้จะถือเป็นเทิร์นอัลตร้า\n·การทำลายล้างจุดเอกฐาน: นำการ์ดที่อยู่ซ้ายสุดในมิติพิเศษออก และสามารถเปิดใช้「Warp จุดเอกฐาน」ครั้งถัดไปในเทิร์นนี้ได้ คูลดาวน์ 3 เทิร์น\n·หลังจากเริ่มการสำรวจ ทีมจะได้รับ DMG Amp. +50％ และรับ「ปริซึมจุดเอกฐาน」15 สะสม\n·「ปริซึมจุดเอกฐาน」: การ์ดคำสั่งทั้งหมดถือว่ามีโบนัสสัญญาณจุดวิกฤติในปริมาณเท่ากัน\n·มิติพิเศษเชี่ยวชาญ: ทุก 1 คะแนนความชำนาญดินแดนของทีม จะเพิ่มจำนวนสะสม「สัญญาณจุดวิกฤติ」ที่「ปริซึมจุดเอกฐาน」และ「เคลื่อนผ่านมิติ」มอบให้ขึ้น 0.05％\n·บริสุทธิ์สูงสุดมิติพิเศษ: หากทีมประกอบด้วยตัวเร่งการตื่นในมิติพิเศษหรือตัวปลุกแห่งความวุ่นวายเท่านั้น ผลของมิติพิเศษเชี่ยวชาญและ DMG Amp. ที่ได้รับจากดินแดนจะเพิ่มเป็นสองเท่า"
  },
